function showSaveFailure(message){let box=$('#saveFailureBanner');if(!box){box=document.createElement('div');box.id='saveFailureBanner';box.className='banner warn';box.setAttribute('role','alert');const text=document.createElement('p');text.className='save-error-text';const backup=document.createElement('button');backup.className='btn';backup.textContent='Esporta le modifiche locali';backup.onclick=()=>download(new Blob([JSON.stringify(state.ws,null,2)],{type:'application/json'}),'Modifiche_locali_da_recuperare.json');box.append(text,backup);$('#main').prepend(box)}box.querySelector('.save-error-text').textContent='Salvataggio non confermato: '+message}
async function persist(){
 const writeRevision=(persist.writeRevision||0)+1;persist.writeRevision=writeRevision;if(!persist.confirmedBaseline&&typeof validationImpactBaseline!=='undefined'&&validationImpactBaseline)persist.confirmedBaseline=structuredClone(validationImpactBaseline);
 if(typeof validationImpactBaseline!=='undefined'&&validationImpactBaseline&&typeof window!=='undefined'&&window.PAIAAValidationLifecycle){try{window.PAIAAValidationLifecycle.enforce(window.PAIAA4,validationImpactBaseline,state.ws);}catch(error){state.ws=structuredClone(validationImpactBaseline);throw error;}}
 if(typeof validationImpactBaseline!=='undefined'&&validationImpactBaseline&&typeof window!=='undefined'&&window.PAIAAValidationImpact){const effects=window.PAIAAValidationImpact.compare(C,window.PAIAA4,window.PAIAAValidationProgress,validationImpactBaseline,state.ws);if(effects.length){if(typeof window.confirm!=='function'||!window.confirm(window.PAIAAValidationImpact.message(effects))){state.ws=structuredClone(validationImpactBaseline);const error=new Error('Aggiornamento annullato: le verifiche precedenti sono state mantenute.');error.code='VALIDATION_UPDATE_CANCELLED';throw error;}for(const effect of effects)C.event(state.ws,'CASE_UPDATED',effect.caseId,{operation:'VALIDATION_IMPACT_ACCEPTED',steps:effect.steps.map(item=>item.id),phases:effect.phases.map(item=>item.number)});}}
 if(state.ws?.cases)for(const caseItem of state.ws.cases)C.applyRules(state.ws,caseItem.id,'BEFORE_WORKSPACE_SAVE');
 if(state.ws&&state.ws.cases)for(const c of state.ws.cases)if(c.workflowTaskSnapshot)wfTrack(c);
 if(typeof validationImpactBaseline!=='undefined'&&validationImpactBaseline&&typeof window!=='undefined'&&window.PAIAAValidationLifecycle){try{window.PAIAAValidationLifecycle.enforce(window.PAIAA4,validationImpactBaseline,state.ws);}catch(error){state.ws=structuredClone(validationImpactBaseline);throw error;}}
 if(typeof window!=='undefined'&&window.PAIAAValidationLifecycle)window.PAIAAValidationLifecycle.captureCompleted(C,window.PAIAA4,window.PAIAAValidationProgress,state.ws,state.user?.username);
 state.ws.meta.updatedAt=C.nowISO();
 // Snapshot per write: a later mutation cannot silently change an earlier pending write.
 const snapshot=structuredClone(state.ws),tenant=state.tenantId;if(typeof validationImpactBaseline!=='undefined')validationImpactBaseline=structuredClone(snapshot);
 savePending++;saveIndicator('Salvataggio in corso…','pending');
 const operation=saveChain.catch(()=>{}).then(async()=>{
  const ok=await D.save(snapshot,tenant);
  if(ok!==true)throw new Error('Il database non ha confermato il salvataggio');
 });
 saveChain=operation;
 try{await operation;persist.confirmedBaseline=structuredClone(snapshot);saveFailure=false;$('#saveFailureBanner')?.remove();return true}
 catch(e){if(persist.writeRevision===writeRevision&&persist.confirmedBaseline&&typeof validationImpactBaseline!=='undefined')validationImpactBaseline=structuredClone(persist.confirmedBaseline);saveFailure=true;saveIndicator('Salvataggio non riuscito','error');showSaveFailure(e.message);throw e}
 finally{
  savePending--;
  if(!saveFailure&&savePending===0&&!assistedDirty&&!assistedTimer)saveIndicator('Modifiche salvate','saved');
  const sm=$('#storageMode');if(sm)sm.textContent=D.mode;
 }
}
async function mutate(fn,msg,{stay=true,anchor=null}={}){const before=C.clone(state.ws),position={questionIndex:state.questionIndex,caseId:state.caseId,caseTab:state.caseTab,docId:state.docId,docReturn:C.clone(state.docReturn??null)};let mutationComplete=false;try{fn();mutationComplete=true;await persist();render();if(anchor)scrollSection(anchor);if(msg)toast(msg);return true;}catch(error){const cancelled=['VALIDATION_UPDATE_CANCELLED','VALIDATION_REVIEW_REQUIRED'].includes(error.code);if(!mutationComplete||cancelled){state.ws=before;Object.assign(state,position);}if(!cancelled)throw error;toast(error.message);return false;}}
function cur(){return state.ws.cases.find(c=>c.id===state.caseId)||state.ws.cases[0]||null}
