let assessmentSaving=false;
async function saveAndAdvanceAssessment(form,advance=true){
 if(assessmentSaving||form.dataset?.completed==='true')return;assessmentSaving=true;document.querySelectorAll('#assessmentFactsForm button,#nextQ').forEach(button=>button.disabled=true);
 try{
  const formIndex=C.QUESTIONS.findIndex(question=>question.id===form.dataset?.question),index=formIndex<0?state.questionIndex:formIndex,q=C.QUESTIONS[index];if(!q)throw Error('Domanda non riconosciuta: riapri la valutazione');
  const raw=Object.fromEntries(new FormData(form)),candidate={...cur(),answers:{...cur().answers,...raw}},check=C.ASSESSMENT4.questionState(candidate,index),data=Object.fromEntries(Object.entries(raw).filter(([key,value])=>C.ASSESSMENT4.valid(key,value)));
  await mutate(()=>{C.saveAssessmentQuestion(state.ws,state.caseId,q.id,data);state.questionIndex=index;if(advance&&check.complete){const next=C.ASSESSMENT4.nextQuestion(cur(),index);if(next>=0)state.questionIndex=next;}cur().wizardProgress={...(cur().wizardProgress||{}),lastStep:state.caseTab,questionIndex:state.questionIndex,updatedAt:C.nowISO()};},check.complete?'Risposta salvata':'Completa i campi indicati sotto la domanda');
  if(state.caseTab==='inherent'){Journey.focus();return}
  if(!check.complete){const message=[...check.missingFields.map(field=>field.label),...check.issues.map(issue=>issue.detail)].join(' · '),status=$('#assessmentValidationStatus');if(status)status.textContent='Per proseguire: '+message;focusAssessmentQuestion('Per proseguire: '+message,check.missing[0]);}
  else{const complete=index===C.QUESTIONS.length-1&&cur().questionnaireCompletedAt?$('#assessmentCompletionOverview'):null;if(complete)requestAnimationFrame(()=>{complete.focus({preventScroll:true});complete.scrollIntoView({block:'start',behavior:'auto'});});else focusAssessmentQuestion();}
 }catch(error){toast(error.message)}finally{assessmentSaving=false;document.querySelectorAll('#assessmentFactsForm button,#nextQ').forEach(button=>button.disabled=$('#assessmentFactsForm')?.dataset.completed==='true')}
}
