function assessmentGroupStatus(c,groups){const qs=C.QUESTIONS.filter(q=>groups.includes(q.group));const answered=qs.filter(q=>c.answers[q.id]).length;return `${answered}/${qs.length} risposte`}
function taskLegend(){return '<p class="microcopy">Genera o apri il documento. Descrizioni, riferimenti e allegati sono disponibili nei dettagli della riga.</p>';}
function taskStatusLabel(s){return {open:'Aperto',in_progress:'In corso',evidence_missing:'Evidenza mancante',under_validation:'Da validare',validated:'Validato',completed:'Completato',non_applicabile:'Non applicabile'}[s]||s}
function tasksOperationalTable(tasks,caseItem){if(caseItem&&typeof window!=='undefined'&&window.PAIAA4?.validationTaskExcluded)tasks=tasks.map(task=>window.PAIAA4.validationTaskExcluded(caseItem,task)?{...task,status:'non_applicabile'}:task);tasks=tasks.filter(task=>task.status!=='non_applicabile'||!state.ws.tasks.some(current=>current.caseId===task.caseId&&current.code===task.code&&current.status!=='non_applicabile'));const labels=docLabels();if(!tasks.length)return '<div class="empty panel">Nessun adempimento per questo filtro.</div>';const completed=tasks.filter(task=>task.status==='non_applicabile'?true:task.status==='completed'&&C.taskReadiness(state.ws,task).ok).length;return `<section class="ops-register" aria-label="Adempimenti del caso"><div class="ops-summary"><span><strong>${tasks.length}</strong> adempimenti</span><span><strong>${completed}</strong> conclusi</span><span><strong>${tasks.length-completed}</strong> da completare</span></div><div id="taskExclusionFeedback" class="banner warn" role="alert" tabindex="-1" hidden></div><div class="table-wrap ops-table-wrap"><table class="ops-table ops-readable" role="table"><caption class="sr-only">Adempimenti, documenti, riscontri e stato del caso ${esc(caseItem?.name||'')}</caption><thead role="rowgroup"><tr role="row"><th scope="col">Adempimento e responsabile</th><th scope="col">Documento</th><th scope="col">Riscontri e allegati</th><th scope="col">Stato</th></tr></thead><tbody role="rowgroup">${tasks.map((task,index)=>{const documentRecord=C.documentForTask(state.ws,task),uploadedDocument=task.documentEvidence?.sourceType==='uploaded-document'?state.ws.evidence.find(item=>item.id===task.documentEvidence.evidenceId&&item.caseId===task.caseId):null,uploadedDocumentCurrent=Boolean(C.taskUploadedDocument?.(state.ws,task)),evs=(task.evidenceIds||[]).map(id=>state.ws.evidence.find(evidence=>evidence.id===id&&evidence.caseId===task.caseId)).filter(Boolean),otherDocs=state.ws.documents.filter(item=>item.caseId===task.caseId&&item.id!==documentRecord?.id&&item.taskIds?.includes(task.id)),validEv=evs.filter(evidence=>evidence.validationStatus==='validated').length,readiness=C.taskReadiness(state.ws,task),exclusionValid=C.taskExclusionValid(state.ws,task),excluded=task.status==='non_applicabile',done=excluded||task.status==='completed'&&readiness.ok,docType=task.docType||'validation_report',documentState=!documentRecord?(excluded?'Non richiesto':'Da generare'):documentRecord.stale?'Da riesaminare':documentRecord.status==='approved'?'Approvato':'Bozza',assetCount=evs.length+otherDocs.length+(documentRecord?1:0),stateText=excluded?'Non applicabile':task.status==='completed'&&!readiness.ok?'Da riesaminare':taskStatusLabel(task.status);const docActions=excluded?'<span class="ops-document-status">Documento: Non richiesto</span>':uploadedDocument?`<strong class="ops-doc-title">${esc(uploadedDocument.name)}</strong><span class="ops-document-status">Documento PDF caricato · ${uploadedDocumentCurrent?'validato':'da riesaminare'}</span><a class="btn small" href="${esc(window.AIGHSecurity.safeDownload(uploadedDocument.dataUrl))}" download="${esc(uploadedDocument.name)}">Apri documento</a>`:documentRecord?`<strong class="ops-doc-title">${esc(documentRecord.title||labels[docType]||docType)}</strong><span class="ops-document-status">Documento: ${esc(documentState)} · v${documentRecord.version}</span><button type="button" class="btn small open-doc" data-id="${esc(documentRecord.id)}" data-task-id="${esc(task.id)}">Modifica / aggiorna</button>`:`<span class="ops-document-status">Documento: Da generare</span><button type="button" class="btn small gen-task-doc" data-task-id="${esc(task.id)}" data-type="${esc(docType)}">Genera documento</button>`;const primary=documentRecord?`<div class="ops-asset"><strong>${esc(documentRecord.title||docType)}</strong><small>Documento generato · v${documentRecord.version} · ${esc(documentState)}</small></div>`:'',documents=otherDocs.map(item=>`<div class="ops-asset"><strong>${esc(item.title||item.type)}</strong><small>Altro documento collegato · v${item.version} · ${item.stale?'Da riesaminare':item.status==='approved'?'Approvato':'Bozza'}</small><button type="button" class="btn tiny open-doc" data-id="${esc(item.id)}">Apri</button></div>`).join(''),files=evs.map(evidence=>`<div class="ops-asset"><strong>${esc(evidence.name)}</strong><small>${evidence.validationStatus==='validated'?'Validato':'Da validare'} · ${fmt(evidence.createdAt)}</small>${evidence.validationStatus!=='validated'?`<button type="button" class="btn tiny success validate-linked-evidence" data-id="${esc(evidence.id)}">Valida file</button>`:''}</div>`).join('');return `<tr id="task-${task.id}" role="row"><td role="cell" data-label="Adempimento e responsabile"><div class="ops-task-heading"><span class="ops-task-number">${index+1}</span><div><strong>${esc(task.title)}</strong><p class="ops-owner">${esc(task.owner||'Da assegnare')}</p></div></div><details class="ops-task-details"><summary>Descrizione e riferimenti</summary><p>${esc(task.description||'')}</p><small>Fonte: ${esc(task.source||'Da specificare')}</small><small>Priorità: ${esc(({critical:'Critica',high:'Alta',medium:'Media',low:'Bassa'})[task.priority]||task.priority||'Da definire')}</small></details></td><td role="cell" data-label="Documento"><div class="ops-document">${docActions}</div></td><td role="cell" data-label="Riscontri e allegati">${excluded?'<p>Non richiesti</p>':`<p class="ops-asset-count">${assetCount?`${assetCount} file ${assetCount===1?'collegato':'collegati'}`:'Nessun file collegato'}</p>${evs.length?`<small>${validEv}/${evs.length} allegati validati</small>`:''}<details class="ops-evidence-details"><summary>${assetCount?'Mostra riscontri':'Riscontro richiesto'}</summary><p>${esc(task.evidenceRequired||'Riscontro documentale dell’adempimento')}</p>${primary}${documents}${files}${!documentRecord&&!excluded?'<p>Documento da predisporre: genera o carica il riscontro.</p>':''}${readiness.documentEvidenceComplete?`<p class="microcopy">Riscontro nel documento confermato da ${esc(task.documentEvidence.by)} · ${esc(task.documentEvidence.scope)}</p>`:''}</details><button type="button" class="btn small upload-for-task" data-id="${esc(task.id)}">Allega file</button>`}</td><td role="cell" data-label="Stato"><div class="ops-state ${done?'is-done':'is-pending'}"><span class="chip task-status task-${esc(task.status)}">${esc(stateText)}</span>${task.validatedAt&&!excluded?`<small>Validato il ${fmt(task.validatedAt)}</small>`:''}${!done&&!excluded&&readiness.reasons.length?`<details class="ops-pending"><summary>Cosa manca</summary><ul>${readiness.reasons.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul></details>`:''}</div></td></tr>`;}).join('')}</tbody></table></div></section>`;}
function evidenceRows(ev){if(!ev.length)return '<div class="empty">Nessuna evidenza caricata.</div>';return ev.map(e=>{const t=e.taskId?state.ws.tasks.find(x=>x.id===e.taskId):null,valid=e.validationStatus==='validated';return `<div class="file-row evidence-validation-row"><div><strong>${esc(e.name)}</strong><br><small>${esc(e.mime||'file')} · ${(e.size/1024).toFixed(1)} KB · ${fmt(e.createdAt)}</small>${t?`<br><small>Collegata a: ${esc(t.title)}</small>`:''}${valid?`<br><small>Validata da ${esc(e.validatedBy)} · ${fmt(e.validatedAt)}</small>`:'<br><small>Validazione richiesta prima della chiusura dell’adempimento.</small>'}</div><div class="chips"><span class="chip ${valid?'validated-evidence':'pending-evidence'}">${valid?'validata':'da validare'}</span>${e.taskId?'<span class="chip">adempimento</span>':''}${e.questionId?'<span class="chip">assessment</span>':''}${valid?`<button class="btn small revoke-evidence" data-id="${e.id}">Revoca validazione</button>`:`<button class="btn success small validate-evidence" data-id="${e.id}">Valida evidenza</button>`}</div></div>`}).join('')}
function documentRequirements(c){const labels=docLabels(),types=C.caseDocumentRequirements(state.ws,c,state.caseTab==='validation'?'validation':'all');return `<div class="doc-requirements">${types.map((type,i)=>{const d=C.latestDocument(state.ws,c.id,type);const reason=type==='case_sheet'?'Identificazione del caso':type==='impact_assessment'?'Sintesi valutazione complessiva':type==='risk_matrix'?'Confronto rischio inerente e rischio residuo dopo le misure':type==='authorization_minutes'?'Decisione finale':type==='monitoring_plan'?'Esercizio e riesame':'Attivato dagli adempimenti del caso';return `<div class="doc-requirement"><span class="doc-order">${i+1}</span><div class="doc-requirement-copy"><strong>${esc(labels[type]||type)}</strong><small>${esc(reason)}</small></div><div class="doc-requirement-actions"><span class="chip">${d?(d.stale?'da riesaminare':d.status):'da generare'}</span>${d?`<button class="btn small doc-requirement-button open-doc" type="button" data-id="${d.id}">Apri</button>`:`<button class="btn small doc-requirement-button gen-required-doc" type="button" data-type="${esc(type)}">Genera</button>`}</div></div>`}).join('')}</div>`}
function incidentRows(caseId){const inc=state.ws.incidents.filter(i=>i.caseId===caseId&&i.status!=='closed');return inc.length?inc.map(i=>`<div class="file-row"><span>${esc(i.title)}</span><span class="chip">${esc(i.severity)}</span></div>`).join(''):'<div class="empty">Nessun incidente aperto.</div>'}
function workflowSteps(c){const comp=C.assessmentCompletion(c),ts=state.ws.tasks.filter(t=>t.caseId===c.id),open=ts.filter(t=>!['completed','non_applicabile'].includes(t.status)),ev=state.ws.evidence.some(e=>e.caseId===c.id),docs=state.ws.documents.some(d=>d.caseId===c.id);const step=(id,label,status,statusLabel,anchor)=>({id,label,status,statusLabel,view:'case-hub',anchor});return [step('case','CASO D’USO','done','creato','overview'),step('assess','ASSESSMENT',comp.complete?'done':'active',comp.pct+'%','assessment'),step('risks','RISCHI',C.riskMatrixData(state.ws,c).after==='Alto'?'hold':(C.riskMatrixData(state.ws,c).before!==C.riskMatrixData(state.ws,c).after?'done':'active'),C.riskMatrixData(state.ws,c).before+' → '+C.riskMatrixData(state.ws,c).after,'risks'),step('tasks','ADEMPIMENTI',open.length?'active':'done',open.length?open.length+' aperti':'chiusi','tasks'),step('evidence','EVIDENZE',ev?'done':'pending',ev?'presenti':'da caricare','evidence'),step('docs','DOCUMENTI',docs?'done':'pending',docs?'presenti':'da generare','documents'),step('auth','AUTORIZZAZIONE',c.authorized?'done':c.status==='ROSSO/HOLD'?'hold':c.status==='VERDE'?'active':'pending',c.authorized?'autorizzato':c.status,'authorization'),step('monitor','MONITORAGGIO',c.authorized?'active':'pending',c.nextReviewAt||'da avviare','monitoring')];}
function renderCaseVisuals(c){const wf=$('#workflowGraph');if(wf)G.workflow(wf,workflowSteps(c),s=>{const d=$('#nodeDetails');if(d)d.innerHTML=`<div class="banner"><strong>${esc(s.label)} — ${esc(s.statusLabel)}</strong><button class="btn small" data-anchor="${s.anchor}">Apri qui sotto</button></div>`;bindAnchors()});const map=$('#caseMap');if(map){const ts=state.ws.tasks.filter(t=>t.caseId===c.id);const nodes=[['Sistema',c.system||'da definire'],['Dati',C.norm(c.answers.personalData)?'personali':'base/da verificare'],['AI Act',c.answers.highRiskPossible||'n.d.'],['Privacy',C.norm(c.answers.personalData)?'attiva':'base'],['Fornitore',c.vendor||'da definire'],['Documenti',state.ws.documents.filter(d=>d.caseId===c.id).length],['Evidenze',state.ws.evidence.filter(e=>e.caseId===c.id).length],['Adempimenti',ts.filter(t=>!['completed','non_applicabile'].includes(t.status)).length],['Stato',c.status]].map(([label,val])=>({label:`${label}: ${val}`,status:c.status}));G.radial(map,c.name,nodes,()=>{})}renderSwim()}
function renderSwim(){const el=$('#swim');if(!el)return;const lanes=[{role:'PROPONENTE',desc:'Descrive il bisogno',steps:['Idea','Caso d’uso','Finalità e KPI']},{role:'RTD',desc:'Governance digitale',steps:['Inquadramento','AI Act','Architettura']},{role:'DPO',desc:'Privacy e diritti',steps:['Registro del trattamento','DPIA','DPA / transfer']},{role:'ICT / SECURITY',desc:'Presidi tecnici',steps:['Accessi','Logging','Incidenti']},{role:'RUP / PROCUREMENT',desc:'Fornitore',steps:['Due diligence','Clausole','Exit']},{role:'RESP. PROCEDIMENTO',desc:'Controllo umano',steps:['Human oversight','Istruttoria','Evidenze']},{role:'DIREZIONE',desc:'Decisione',steps:['Autorizzazione','Condizioni']},{role:'AI OWNER',desc:'Esercizio',steps:['Monitoraggio','Riesame']}];G.swimlane(el,lanes,x=>toast(x.role+' → '+x.label))}

function docsTable(docs){return (docs.length?`<div class="table-wrap"><table><thead><tr><th>Documento</th><th>Versione</th><th>Stato</th><th>Ultima modifica</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr class="doc-row ${d.stale?'stale':''}"><td><strong>${esc(d.title)}</strong>${d.stale?`<br><small>Da riesaminare: ${esc(d.staleReason)}</small>`:''}</td><td>v${d.version}</td><td>${esc(d.status)} ${d.stale?'<span class="chip">da riesaminare</span>':''}</td><td>${fmt(d.updatedAt)}</td><td><button class="btn small open-doc" data-id="${d.id}">Apri</button>${['validation_report','authorization_minutes'].includes(d.type)&&d.status==='draft'&&!d.approvedAt&&!d.versions?.some(v=>v.reason==='Approvazione')?`<button class="btn danger small discard-validation-draft" data-id="${esc(d.id)}">Elimina bozza verbale</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty panel">Nessun documento generato.</div>')+`<details><summary>Bozze verbali eliminate</summary>${(state.ws.documentDraftTrash||[]).filter(item=>item.document.caseId===state.caseId).map(item=>`<p>${esc(item.document.title)} <button class="btn small restore-validation-draft" data-id="${esc(item.document.id)}">Ripristina bozza</button></p>`).join('')||'<p>Nessuna bozza eliminata.</p>'}</details>`}
function registerView(){const rows=state.ws.cases.map(c=>`<tr><td>${esc(c.id)}</td><td><button class="link-btn open-case" data-id="${c.id}">${esc(c.name)}</button></td><td>${esc(c.system)}</td><td>${esc(c.owner)}</td><td>${statusBadge(c.status)}</td><td>${esc(c.vendor)}</td><td>${esc(c.nextReviewAt||'—')}</td></tr>`).join('');return page('Registro AI','Inventario unico dei casi d’uso, collegato ai rispettivi fascicoli.',`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Caso</th><th>Sistema</th><th>Owner</th><th>Stato</th><th>Fornitore</th><th>Riesame</th></tr></thead><tbody>${rows}</tbody></table></div>`,`<button class="btn" id="genRegister">Genera documento Registro AI</button>`)}
function incidentsView(){const rows=state.ws.incidents.map(i=>`<tr><td><strong>${esc(i.title)}</strong><br><small>${esc(i.category||'Altro')}</small></td><td>${esc(state.ws.cases.find(c=>c.id===i.caseId)?.name||'—')}</td><td><span class="priority ${esc(i.severity)}">${esc(i.severity)}</span></td><td>${esc(i.owner||'—')}</td><td>${i.dueDate?esc(i.dueDate):'—'}</td><td>${esc(i.status)}</td><td><span class="chip">${(i.attachments||[]).length} doc</span></td><td><div class="actions"><button class="btn small edit-incident" data-id="${i.id}">Apri scheda</button><button class="btn small open-task-case" data-id="${i.caseId}">Fascicolo</button></div></td></tr>`).join('');return page('Incidenti AI','Scheda completa di incidente con impatto, azioni, documenti, owner e scadenze.',`<button class="btn primary" id="newIncidentGlobal">Registra incidente</button><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Incidente</th><th>Caso</th><th>Severità</th><th>Owner</th><th>Scadenza</th><th>Stato</th><th>Allegati</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="8" class="empty">Nessun incidente.</td></tr>'}</tbody></table></div>`)}
function reviewsView(){const rows=state.ws.cases.map(c=>{const controls=Array.isArray(c.monitoringControls)?c.monitoringControls:[],openControls=controls.filter(x=>x.status!=='done').length;return `<tr><td>${esc(c.name)}</td><td>${c.reassessmentRequired?'<span class="status review">richiesto</span>':'programmato'}</td><td>${c.lastReviewAt?fmt(c.lastReviewAt):'—'}</td><td>${esc(c.nextReviewAt||'—')}</td><td><strong>${openControls}</strong> aperti / ${controls.length} totali</td><td><div class="actions"><button class="btn small add-review-control" data-id="${c.id}">Aggiungi controllo</button><button class="btn small review-case" data-id="${c.id}">Apri monitoraggio</button></div></td></tr>`}).join('');return page('Riesami','Programma scadenze e aggiungi controlli specifici per ogni caso. Le modifiche rilevanti riportano il caso nel ciclo di valutazione.',`<div class="banner"><strong>Procedura di riesame</strong> Definisci i controlli da svolgere, assegna una scadenza, registra l’esito e programma il riesame successivo.</div><div class="table-wrap"><table><thead><tr><th>Caso</th><th>Stato</th><th>Ultimo</th><th>Prossimo</th><th>Controlli</th><th>Azioni</th></tr></thead><tbody>${rows}</tbody></table></div>`)}
function trainingView(){const rows=state.ws.training.map(t=>`<tr><td><strong>${esc(t.person)}</strong><br><small>${esc(t.role||'—')}</small></td><td>${esc(t.course)}</td><td>${esc(t.provider||'—')}</td><td>${esc(t.date||'—')}</td><td>${esc(t.dueDate||t.expiryDate||'—')}</td><td>${esc(t.status)}</td><td><span class="chip">${(t.attachments||[]).length} doc</span></td><td><button class="btn small edit-training" data-id="${t.id}">Apri scheda</button></td></tr>`).join('');return page('Formazione / AI Literacy','Registro completo delle competenze con documenti, pianificazione, scadenze e rinnovi.',`<button class="btn primary" id="addTraining">Registra formazione</button><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Persona / ruolo</th><th>Corso</th><th>Ente / provider</th><th>Data</th><th>Scadenza / rinnovo</th><th>Stato</th><th>Allegati</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="8" class="empty">Nessuna formazione registrata.</td></tr>'}</tbody></table></div>`)}
function deadlinesView(embedded=false){const items=deadlineItems(),month=state.deadlineMonth||new Date().toISOString().slice(0,7),[y,m]=month.split('-').map(Number),first=new Date(y,m-1,1),last=new Date(y,m,0),start=(first.getDay()+6)%7,days=last.getDate(),cells=[];for(let i=0;i<start;i++)cells.push('<div class="cal-day empty-day"></div>');for(let d=1;d<=days;d++){const date=`${month}-${String(d).padStart(2,'0')}`,dayItems=items.filter(x=>x.date===date);cells.push(`<div class="cal-day ${date===new Date().toISOString().slice(0,10)?'today':''}"><strong>${d}</strong>${dayItems.slice(0,4).map(x=>`<button class="cal-event deadline-open" data-id="${esc(x.id)}" title="${esc(x.title)}"><span>${esc(x.type)}</span>${esc(x.title)}</button>`).join('')}${dayItems.length>4?`<small>+${dayItems.length-4} altre</small>`:''}</div>`)}const owners=[...new Set(items.map(x=>x.owner).filter(Boolean))].sort();const filtered=state.deadlinePerson==='all'?items:items.filter(x=>x.owner===state.deadlinePerson);const content=`<div class="deadline-toolbar"><div class="actions"><button class="btn" id="prevDeadlineMonth">←</button><strong>${first.toLocaleDateString('it-IT',{month:'long',year:'numeric'})}</strong><button class="btn" id="nextDeadlineMonth">→</button><button class="btn small" id="deadlineToday">Oggi</button></div><label class="field compact-field"><span>Persona / owner</span><select id="deadlinePerson"><option value="all">Tutti</option>${owners.map(o=>`<option ${state.deadlinePerson===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label></div><div class="calendar panel"><div class="cal-head">${['Lun','Mar','Mer','Gio','Ven','Sab','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="cal-grid">${cells.join('')}</div></div><div class="panel deadline-list-panel"><div class="section-head"><div><span class="eyebrow">LISTA</span><h3>Tutte le scadenze</h3></div><span class="chip">${filtered.length}</span></div><div class="deadline-list">${filtered.length?filtered.map(x=>`<div class="deadline-row ${x.date<new Date().toISOString().slice(0,10)?'overdue':''}"><div class="deadline-date"><strong>${esc(x.date||'—')}</strong><small>${esc(x.type)}</small></div><div class="deadline-main"><strong>${esc(x.title)}</strong><small>${esc(state.ws.cases.find(c=>c.id===x.caseId)?.name||'Nessun caso')} · ${esc(x.owner||'Da assegnare')}</small></div><span class="chip">${esc(x.status||'aperto')}</span><div class="actions"><button class="btn small deadline-open" data-id="${esc(x.id)}">Apri</button><button class="btn small reassign-deadline" data-id="${esc(x.id)}">Riassegna</button></div></div>`).join(''):'<div class="empty">Nessuna scadenza.</div>'}</div></div>`;return embedded?`<div class="embedded-dashboard-view"><div class="section-head"><div><h3>Scadenze</h3><p>Calendario unico di adempimenti, riesami, controlli, incidenti e formazione.</p></div><button class="btn small" data-view="deadlines">Apri pagina completa</button></div>${content}</div>`:page('Scadenze','Calendario unico di adempimenti, riesami, controlli, incidenti e formazione.',content)}
function todoCaseGroups(items,cases,options={},today=new Date().toLocaleDateString('en-CA')){
 const valid=d=>/^\d{4}-\d{2}-\d{2}$/.test(String(d||'').slice(0,10))&&!Number.isNaN(Date.parse(String(d).slice(0,10)+'T00:00:00Z'));
 const day=d=>Math.floor(Date.parse(d+'T00:00:00Z')/86400000),date=d=>valid(d)?String(d).slice(0,10):'';
 const groups=new Map();
 for(const item of items){const c=cases.find(c=>c.id===item.caseId),opened=date(c?.createdAt),due=date(item.date),delta=due?day(due)-day(today):null;
 const urgency=delta===null?'undated':delta<0?'overdue':delta<=7?'soon':'planned';
 if(options.owner&&options.owner!=='all'&&item.owner!==options.owner&&!(item.relatedItems||[]).some(r=>r.owner===options.owner))continue;
 if(options.urgency&&options.urgency!=='all'&&urgency!==options.urgency)continue;
 if(options.from&&(!opened||opened<options.from))continue;if(options.to&&(!opened||opened>options.to))continue;
 const key=c?.id||'unlinked',label=c?.name||'Attività senza caso collegato';
 if(options.query&&!(label+' '+item.title+' '+item.owner).toLocaleLowerCase('it').includes(options.query.toLocaleLowerCase('it')))continue;
 if(!groups.has(key))groups.set(key,{id:key,name:label,opened,age:opened?Math.max(0,day(today)-day(opened)):null,items:[]});
 groups.get(key).items.push({...item,due,urgency,delta});
 }
 const rank={overdue:0,soon:1,planned:2,undated:3};
 for(const g of groups.values()){g.items.sort((a,b)=>rank[a.urgency]-rank[b.urgency]||String(a.due||'9999').localeCompare(b.due||'9999')||a.title.localeCompare(b.title));g.rank=Math.min(...g.items.map(x=>rank[x.urgency]));g.next=g.items.find(x=>x.due)?.due||'9999';}
 return [...groups.values()].sort((a,b)=>options.sort==='oldest'?String(a.opened||'9999').localeCompare(b.opened||'9999'):options.sort==='newest'?String(b.opened||'0000').localeCompare(a.opened||'0000'):a.rank-b.rank||a.next.localeCompare(b.next)||String(a.opened||'9999').localeCompare(b.opened||'9999'));
}
function todosView(embedded=false){
 const all=todoItems(),ui=state.todoUi||{urgency:'all',sort:'priority',from:'',to:'',query:''},today=new Date().toLocaleDateString('en-CA'),owners=[...new Set(all.flatMap(x=>(x.relatedItems||[x]).map(r=>r.owner)).filter(Boolean))].sort(),groups=todoCaseGroups(all,state.ws.cases,{...ui,owner:state.deadlinePerson},today),visible=groups.flatMap(g=>g.items),count=k=>visible.filter(x=>x.urgency===k).length;
 const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('it-IT'):'Data non registrata',urgencyLabel=x=>x.urgency==='overdue'?'Scaduta da '+Math.abs(x.delta)+' giorni':x.urgency==='soon'?(x.delta===0?'Scade oggi':'Entro '+x.delta+' giorni'):x.urgency==='undated'?'Scadenza da definire':'Programmata';
 const content=`<section aria-labelledby="openTasksHeading"><div class="section-head"><div><span class="eyebrow">AGENDA PER CASO</span><h3 id="openTasksHeading">Attività aperte</h3><p>Prima le scadute, poi quelle entro 7 giorni. A parità di urgenza e scadenza, precedono i casi aperti da più tempo.</p></div><span class="chip">${visible.length} attività · ${groups.length} casi / gruppi</span></div>${all.some(x=>x.duplicateCount||x.linkIssue)?`<div class="banner warn"><strong>Controllo coerenza</strong><p>${all.reduce((n,x)=>n+(x.duplicateCount||0),0)} ripetizioni riunite per caso e codice attività; ${all.filter(x=>x.linkIssue).length} attività con collegamento al caso da verificare. Le registrazioni originali sono conservate nei dettagli.</p></div>`:''}<div class="open-task-summary" aria-label="Riepilogo attività filtrate"><div><strong>${count('overdue')}</strong><span>Scadute</span></div><div><strong>${count('soon')}</strong><span>Entro 7 giorni</span></div><div><strong>${count('undated')}</strong><span>Senza scadenza</span></div></div><div class="panel open-task-filters"><label class="field"><span>Cerca caso, attività o responsabile</span><input type="search" id="todoSearch" value="${esc(ui.query)}" placeholder="Nome o parola chiave"></label><label class="field"><span>Responsabile</span><select id="todoPerson"><option value="all">Tutti i responsabili</option>${owners.map(o=>`<option ${state.deadlinePerson===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label><label class="field"><span>Scadenza</span><select id="todoUrgency">${[['all','Tutte le attività'],['overdue','Scadute'],['soon','Oggi ed entro 7 giorni'],['undated','Senza scadenza'],['planned','Oltre 7 giorni']].map(([v,l])=>`<option value="${v}" ${ui.urgency===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="field"><span>Ordina i casi</span><select id="todoSort">${[['priority','Urgenza e scadenza'],['oldest','Apertura: meno recenti prima'],['newest','Apertura: più recenti prima']].map(([v,l])=>`<option value="${v}" ${ui.sort===v?'selected':''}>${l}</option>`).join('')}</select></label><details class="todo-date-filter"><summary>Filtra per apertura del caso</summary><div class="grid two"><label class="field"><span>Aperto dal</span><input type="date" id="todoFrom" value="${esc(ui.from)}"></label><label class="field"><span>Aperto entro il</span><input type="date" id="todoTo" value="${esc(ui.to)}"></label></div><p class="microcopy">Usa la data di creazione del fascicolo; i casi senza data sono esclusi quando imposti questo filtro.</p></details><button class="btn small" id="todoReset" type="button">Azzera filtri</button></div><p role="status">${ui.from&&ui.to&&ui.from>ui.to?'Intervallo non valido: la data iniziale deve precedere quella finale.':groups.length?'Apri un caso per consultare le attività e le azioni disponibili.':'Nessuna attività corrisponde ai filtri.'}</p><div class="open-task-cases">${groups.map((g,i)=>`<details class="panel agenda-case-card" ${i===0?'open':''}><summary><span class="todo-case-name">${esc(g.name)}</span><span class="todo-case-dates">Apertura: ${dateLabel(g.opened)}${g.age!==null?' · '+g.age+' giorni dall’apertura':''}</span><span class="chip">${g.items.length} attività${g.items.some(x=>x.urgency==='overdue')?' · '+g.items.filter(x=>x.urgency==='overdue').length+' scadute':''}</span></summary><ul class="open-task-rows">${g.items.slice((state.todoPages?.[g.id]||0)*5,((state.todoPages?.[g.id]||0)+1)*5).map(x=>`<li class="open-task-row urgency-${x.urgency}"><div><strong>${esc(x.title)}</strong><p>${esc(x.type)} · ${esc(x.owner||'Da assegnare')} · ${esc(taskStatusLabel(x.status))}</p>${x.linkIssue?'<p class="risk-note">Caso collegato non trovato: verificare l’associazione.</p>':''}${x.duplicateCount?`<details><summary>${x.relatedItems.length} registrazioni per lo stesso adempimento · da riesaminare</summary><p>Scadenza in evidenza: la prima disponibile. Ogni registrazione mantiene responsabile, stato e prove.</p><ul>${x.relatedItems.map(r=>`<li><code>${esc(r.sourceId)}</code> · ${esc(r.owner)} · ${esc(taskStatusLabel(r.status))} · ${esc(r.date||'Senza scadenza')} <button class="btn small reassign-deadline" data-id="${esc(r.id)}">Riassegna questa registrazione</button></li>`).join('')}</ul></details>`:''}<span class="todo-due">${esc(urgencyLabel(x))}${x.due?' · '+dateLabel(x.due):''}</span></div><div class="actions"><button class="btn small deadline-open" data-id="${esc(x.id)}" aria-label="Apri attività: ${esc(x.title)} nel caso ${esc(g.name)}">Apri attività</button>${!x.duplicateCount?`<button class="btn small reassign-deadline" data-id="${esc(x.id)}" aria-label="Riassegna ${esc(x.title)}">Riassegna</button>`:''}</div></li>`).join('')}</ul>${g.items.length>5?`<div class="actions todo-pagination" aria-label="Pagine attività di ${esc(g.name)}"><button class="btn small" data-todo-case="${esc(g.id)}" data-todo-page="${(state.todoPages?.[g.id]||0)-1}" ${(state.todoPages?.[g.id]||0)===0?'disabled':''}>Precedenti</button><span>Pagina ${(state.todoPages?.[g.id]||0)+1} di ${Math.ceil(g.items.length/5)} · 5 attività per pagina</span><button class="btn small" data-todo-case="${esc(g.id)}" data-todo-page="${(state.todoPages?.[g.id]||0)+1}" ${((state.todoPages?.[g.id]||0)+1)*5>=g.items.length?'disabled':''}>Successive</button></div>`:''}</details>`).join('')}</div></section>`;
 return embedded?`<div class="embedded-dashboard-view"><div class="section-head"><h3>Cose da fare</h3><button class="btn small" data-view="todos">Apri pagina completa</button></div>${content}</div>`:page('Cose da fare','Agenda delle attività raggruppate per caso, con scadenze e data di apertura del fascicolo.',content);
}
function bindTodoFilters(){$$('[data-todo-page]').forEach(b=>b.onclick=()=>{state.todoPages={...state.todoPages,[b.dataset.todoCase]:Number(b.dataset.todoPage)};render();document.querySelector('.agenda-case-card')?.scrollIntoView({block:'start'});document.querySelector('[data-todo-case="'+b.dataset.todoCase+'"]:not([disabled])')?.focus()});const ids={todoSearch:'query',todoUrgency:'urgency',todoSort:'sort',todoFrom:'from',todoTo:'to'};for(const [id,key] of Object.entries(ids)){const el=document.getElementById(id);if(el)el.onchange=()=>{state.todoUi={urgency:'all',sort:'priority',from:'',to:'',query:'',...state.todoUi,[key]:el.value};state.todoPages={};render();document.getElementById(id)?.focus()}}const reset=document.getElementById('todoReset');if(reset)reset.onclick=()=>{state.todoUi=null;state.todoPages={};state.deadlinePerson='all';render();document.getElementById('todoReset')?.focus()};}

function sourcesView(){const rows=C.SOURCE_MATRIX.map(s=>`<tr><td><strong>${esc(s.source)}</strong><br><span class="source-state ${/bozza|iter/i.test(s.status)?'draft':''}">${esc(s.status)}</span></td><td>${esc(s.requirement)}</td><td>${esc(s.question)}</td><td>${esc(s.task)}</td><td>${esc(s.evidence)}</td><td>${esc(s.document)}</td><td>${esc(s.control)}</td><td>${esc(s.monitoring)}</td></tr>`).join('');return page('Matrice fonti → requisiti','La matrice è la catena logica del motore di assessment e adempimenti.',`<div class="table-wrap"><table><thead><tr><th>Fonte</th><th>Requisito</th><th>Domanda</th><th>Adempimento</th><th>Evidenza</th><th>Documento</th><th>Controllo</th><th>Monitoraggio</th></tr></thead><tbody>${rows}</tbody></table></div>`)}
function normativaView(){return page('Normativa e riferimenti','Il portale funziona offline; l’apertura delle fonti esterne richiede una connessione Internet.',`<div id="regulatoryMonitor" class="panel" aria-label="Aggiornamenti normativi"></div><div class="banner warn"><strong>Nota sui collegamenti</strong> I link seguenti sono esterni. Se il PC è offline usa “Copia link” e aprilo successivamente da una postazione connessa.</div><div class="grid two">${C.SOURCE_MATRIX.map((s,i)=>`<div class="panel"><h3>${esc(s.source)}</h3><p>${esc(s.requirement)}</p><div class="chips"><span class="chip">${esc(s.status)}</span><span class="chip">${esc(s.id)}</span></div><div class="actions"><a class="btn source-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Apri online</a><button class="btn copy-source" data-url="${esc(s.url)}">Copia link</button></div></div>`).join('')}</div>`)}
function guideView(){return page('Guida all’uso','La guida segue lo stesso ordine del fascicolo.',`<div class="guide-hero"><div><span class="eyebrow">PERCORSO IN 8 PASSI</span><h3>Un caso AI = un fascicolo unico</h3><p>Assessment, adempimenti, evidenze, documenti, decisione e monitoraggio restano collegati nello stesso fascicolo.</p></div><button class="btn primary" data-view="case-hub" data-anchor="overview">Apri il fascicolo corrente</button></div><div class="guide-steps">${[['1','Sintesi','Controlla stato e prossime azioni.'],['2','Assessment','Completa le 13 domande e le valutazioni Registro del trattamento/DPIA.'],['3','Rischi','Valuta e valida rischio inerente e residuo.'],['4','Adempimenti','Carica file e gestisci il documento direttamente dalla stessa riga.'],['5','Evidenze','Valida i file e consulta anche i documenti collegati.'],['6','Documenti','Genera, modifica, versiona e approva.'],['7','Autorizzazione','Registra la decisione solo quando il fascicolo è pronto.'],['8','Monitoraggio','Definisci owner, frequenza, scadenza e storico dei riesami.']].map(([n,t,d])=>`<div class="guide-step"><span>${n}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</div><div class="grid two"><div class="panel"><h3>Adempimenti ed evidenze</h3><p>I file caricati sono visibili sotto il singolo adempimento; possono essere validati lì o nel tab Evidenze. Lo stato del documento collegato è sempre visibile e sincronizzato.</p></div><div class="panel"><h3>Monitoraggio</h3><p>Imposta una data, un owner e una frequenza. Le scadenze scadute o entro 30 giorni sono riportate anche in dashboard.</p></div></div><div class="panel" style="margin-top:14px"><h3>Ruoli applicativi</h3><p><strong>Admin</strong>: configurazione dell’Ente e funzioni amministrative. <strong>User</strong>: operatività completa sui fascicoli senza funzioni di amministrazione. Le sezioni <strong>Scadenze</strong> e <strong>Cose da fare</strong> aggregano automaticamente adempimenti, riesami, controlli, incidenti e formazione per data e persona.</p></div>`)}
function helpdeskView(){return page('Help desk','Orientamento locale per l’uso della piattaforma.',`<div class="support-grid"><div class="panel support-card"><span class="eyebrow">GUIDA</span><h3>Percorso operativo</h3><p>Consulta le istruzioni aggiornate sul fascicolo, le evidenze e il monitoraggio.</p><button class="btn primary" data-view="guide">Apri guida</button></div><div class="panel support-card"><span class="eyebrow">DIAGNOSTICA</span><h3>Controlla l’ambiente</h3><p>Verifica integrità workspace, storage e collegamenti.</p><button class="btn" data-view="support">Apri diagnostica</button></div><div class="panel support-card"><span class="eyebrow">ACCESSIBILITÀ</span><h3>Preferenze interfaccia</h3><p>Testo grande, contrasto e riduzione movimento.</p><button class="btn" data-view="accessibility">Apri preferenze</button></div></div>`)}
function administrationTools(){if(!isAdmin())return '';return `<div class="panel" style="margin-bottom:16px"><h3>Ripristino e gestione server</h3><div class="actions"><button class="btn" id="restoreImport">Ripristina copia precedente all’importazione</button>${D.isServer?'<button class="btn" id="createServerUser">Crea utente server</button><button class="btn" id="downloadServerAudit">Esporta audit server</button>':''}</div></div>`}
async function restoreImport(){if(!isAdmin())return;confirmAction('Ripristinare la copia precedente all’ultima importazione? Le modifiche attuali saranno sostituite.',async()=>{try{await flushDocumentEditor();const ws=await D.restorePreImport(state.tenantId);state.ws=normalizeWorkspace(window.AIGHSecurity.workspace(ws).workspace);state.caseId=state.ws.cases[0]?.id||null;state.docId=null;render();toast('Copia precedente ripristinata')}catch(e){toast(e.message)}})}
function createServerUser(){if(!isAdmin()||!D.isServer)return;const m=modal('Nuovo utente server',`<form id="serverUserForm" class="form-grid"><label class="field"><span>Nome utente</span><input name="username" required pattern="[A-Za-z0-9_.-]+" maxlength="64" autocomplete="off"></label><label class="field"><span>Password (almeno 12 caratteri)</span><input name="password" required type="password" minlength="12" maxlength="256" autocomplete="new-password"></label><label class="field"><span>Ruolo</span><select name="role"><option>Utente tenant</option><option>Amministratore</option></select></label><button class="btn primary" type="submit">Crea utente</button><p id="serverUserError" role="alert"></p></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{await D.createUser(data.username,data.password,data.role);await refreshTenantDirectory();m.remove();toast('Utente server creato')}catch(err){m.querySelector('#serverUserError').textContent=err.message}}}
function supportView(){const v=C.validateWorkspace(state.ws),badSources=C.SOURCE_MATRIX.filter(s=>!/^https:\/\//.test(s.url||''));return page('Supporto e diagnostica','Strumenti per controllare il funzionamento, esportare dati e risolvere problemi senza link interni ambigui.',`${administrationTools()}<div class="grid two"><div class="panel"><h3>Stato applicazione</h3><div class="diagnostic-list"><div class="diagnostic-row"><span>Versione</span><strong>v${C.APP_VERSION}</strong></div><div class="diagnostic-row"><span>Storage</span><strong>${esc(D.mode)}</strong></div><div class="diagnostic-row"><span>Integrità workspace</span><strong>${v.ok?'OK':'ERRORE'}</strong></div><div class="diagnostic-row"><span>Casi</span><strong>${state.ws.cases.length}</strong></div><div class="diagnostic-row"><span>Documenti</span><strong>${state.ws.documents.length}</strong></div><div class="diagnostic-row"><span>Link fonti malformati</span><strong>${badSources.length}</strong></div></div></div><div class="panel"><h3>Portabilità e ripristino</h3><div class="actions"><button class="btn primary" id="exportJson">Esporta workspace JSON</button><button class="btn" id="backupZip">Backup ZIP</button><button class="btn" id="supportImport">Importa JSON</button>${isAdmin()?'<button class="btn danger" id="supportReset">Reset controllato</button>':'<span class="chip">Reset solo admin</span>'}</div><p><small>Il reset cancella il workspace locale dopo conferma. Il backup ZIP contiene workspace e documenti HTML.</small></p></div></div><div class="panel" style="margin-top:14px"><h3>Controllo navigazione</h3><p>Tutte le funzioni principali sono raggiunte tramite route interne esplicite. Nel fascicolo le sei fasi sono schede separate: non esistono più ancore che scorrono in una pagina unica.</p><div class="chips"><span class="chip">Dashboard</span><span class="chip">Casi</span><span class="chip">Fascicolo</span><span class="chip">Configurazione</span><span class="chip">Guida</span><span class="chip">Help desk</span><span class="chip">Normativa</span></div></div>`)}
function accessibilityView(){return page('Accessibilità','Preferenze e criteri applicati all’interfaccia.',`<div class="grid two"><div class="panel"><h3>Preferenze</h3><button class="btn" id="accText" aria-pressed="${document.body.classList.contains('large-text')}">Testo grande</button> <button class="btn" id="accContrast" aria-pressed="${document.body.classList.contains('high-contrast')}">Alto contrasto</button> <button class="btn" id="accMotion" aria-pressed="${document.body.classList.contains('reduce-motion')}">Riduci movimento</button></div><div class="panel"><h3>Progettazione</h3><p>Skip navigation, focus visibile, tastiera, etichette esplicite, stato testuale oltre al colore, grafici accessibili, menu richiudibile e navigazione interna per sezioni.</p></div></div>`)}

function normalizeWorkspace(ws){if(!D.isServer&&window.PAIAAPresentation.needsRefresh(ws))window.PAIAAPresentation.add(ws);for(const k of ['responses','vendors','events','incidents','training','reviews','authorizations','decisions','supportRequests'])if(!Array.isArray(ws[k]))ws[k]=[];if(!Array.isArray(ws.catalogExamples))ws.catalogExamples=[];ws.settings=ws.settings||{};ws.entity=ws.entity||{};if(/^comune di esempio$/i.test(ws.entity.name||''))ws.entity.name='Ente di Esempio';if(/^comune$/i.test(ws.entity.type||''))ws.entity.type='Ente';for(const k of ['address','email','pec','phone'])if(typeof ws.entity[k]!=='string')ws.entity[k]='';ws.entity.roles=ws.entity.roles||[];for(const r of ws.entity.roles){if(!r.function&&r.responsibility)r.function=r.responsibility;r.function=r.function||'';r.involvement=r.involvement||'';r.state=r.state||'';r.evidence=r.evidence||'';r.notes=r.notes||'';delete r.responsibility}for(const c of ws.cases||[]){c.ropaStatus=c.ropaStatus||'non_verificato';c.ropaNote=c.ropaNote||'';c.dpiaDecision=c.dpiaDecision||'non_valutata';c.dpiaReason=c.dpiaReason||'';c.dpiaValidatedBy=c.dpiaValidatedBy||'';c.dpiaValidatedAt=c.dpiaValidatedAt||null;c.riskValidation=c.riskValidation||'';c.riskValidationReason=c.riskValidationReason||'';c.riskValidatedBy=c.riskValidatedBy||'';c.riskValidatedAt=c.riskValidatedAt||null;c.riskHistory=Array.isArray(c.riskHistory)?c.riskHistory:[];c.processorName=c.processorName||'';c.processorActRef=c.processorActRef||'';c.processorActDate=c.processorActDate||'';c.processorScope=c.processorScope||'';c.residualRiskAccepted=Boolean(c.residualRiskAccepted);c.residualRiskAcceptedBy=c.residualRiskAcceptedBy||'';c.residualRiskAcceptedAt=c.residualRiskAcceptedAt||null;c.residualRiskAcceptanceNote=c.residualRiskAcceptanceNote||'';c.monitoringOwner=c.monitoringOwner||c.owner||'';c.monitoringFrequency=c.monitoringFrequency||'trimestrale';c.monitoringNote=c.monitoringNote||'';c.monitoringControls=Array.isArray(c.monitoringControls)?c.monitoringControls:[];for(const m of c.monitoringControls){m.owner=m.owner||c.monitoringOwner||c.owner||''}}for(const i of ws.incidents||[]){i.category=i.category||'Altro';i.impact=i.impact||'';i.containment=i.containment||'';i.rootCause=i.rootCause||'';i.correctiveActions=i.correctiveActions||'';i.dueDate=i.dueDate||'';i.attachments=Array.isArray(i.attachments)?i.attachments:[];i.reassignmentHistory=Array.isArray(i.reassignmentHistory)?i.reassignmentHistory:[]}for(const t of ws.training||[]){t.provider=t.provider||'';t.mode=t.mode||'Aula / webinar';t.hours=Number(t.hours||0);t.dueDate=t.dueDate||'';t.expiryDate=t.expiryDate||'';t.owner=t.owner||t.person||'';t.notes=t.notes||'';t.attachments=Array.isArray(t.attachments)?t.attachments:[];t.reassignmentHistory=Array.isArray(t.reassignmentHistory)?t.reassignmentHistory:[]}return C.migrateWorkspaceV2(ws)}
function applyTheme(theme){const dark=theme==='dark';document.body.classList.toggle('theme-dark',dark);try{localStorage.setItem('aigh_theme',dark?'dark':'light')}catch(e){}}
function tenantIconMarkup(t){if(t?.logo)return `<img src="${esc(t.logo)}" alt="">`;return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20V9l8-5 8 5v11M8 12h2m4 0h2M8 16h2m4 0h2"/></svg>`}
function updateHeaderIdentity(){const t=state.tenants.find(x=>x.id===state.tenantId);const name=$('#tenantHeaderName'),logo=$('#tenantHeaderLogo'),un=$('#headerUserName'),ur=$('#headerUserRole'),cfg=document.querySelector('.top-tool[data-view="entity"]');if(name)name.textContent=entityLabel(state.ws?.entity?.name||t?.name);if(logo)logo.innerHTML=tenantIconMarkup({logo:state.ws?.entity?.logo||t?.logo||''});if(un)un.textContent=state.user?.username||'admin';if(ur)ur.textContent=state.user?.role||'Amministratore';if(cfg)cfg.classList.toggle('hidden',!isAdmin())}
async function refreshTenantDirectory(){state.tenants=await D.listTenants();return state.tenants}
async function refreshLoginTenants(){const list=await refreshTenantDirectory(),t=list[0],sel=$('#loginTenant'),name=$('#loginEntityName');if(sel){sel.innerHTML=t?`<option value="${esc(t.id)}" selected>${esc(entityLabel(t.name))}</option>`:''}if(name)name.textContent=entityLabel(t?.name||'Ente configurato');return list}
async function switchTenant(id){const only=(await refreshTenantDirectory())[0];if(!only)return;state.tenantId=only.id;D.setCurrentTenant(only.id);return only}
function openTenantSwitcher(){toast('Installazione mono-Ente: non sono previsti altri enti')}
function createTenantDialog(){toast('Installazione mono-Ente: configura l’Ente dalla sezione Configurazione')}
async function saveEntityLogo(file){if(!file)return;if(file.size>400_000){toast('Logo troppo grande: massimo 400 KB');return}const ok=/^image\/(png|jpeg|webp)$/.test(file.type);if(!ok){toast('Formato logo non supportato');return}const data=await readDataUrl(file);state.ws.entity.logo=data;const t=await D.updateTenant(state.tenantId,{logo:data,name:state.ws.entity.name,type:state.ws.entity.type,city:state.ws.entity.city});await refreshTenantDirectory();await persist();render();toast('Logo dell’Ente salvato')}
function editorView(doc){const linkedTask=state.docReturn?.taskId?state.ws.tasks.find(item=>item.id===state.docReturn.taskId&&item.caseId===doc.caseId):null;const caseName=doc.caseId?state.ws.cases.find(c=>c.id===doc.caseId)?.name:'';return page(doc.title,`${caseName?caseName+' · ':''}Versione ${doc.version} · ${doc.status}${doc.stale?' · DA RIESAMINARE':''}`,`${doc.stale?`<div class="banner warn"><strong>Documento da riesaminare</strong>${esc(doc.staleReason)}</div>`:''}${doc.requirementCodes?.length?`<p class="banner">Adempimenti normativi collegati: ${doc.requirementCodes.map(code=>esc((doc.caseId&&C.getCase(state.ws,doc.caseId)?window.PAIAA4.requirements(C.getCase(state.ws,doc.caseId)).find(row=>row.code===code)?.title:null)||code)).join(' · ')}. L’approvazione del documento non sostituisce la verifica di pertinenza dell’adempimento.</p>`:''}${doc.taskIds?.length?`<p class="microcopy">${doc.taskIds.length} adempimenti operativi collegati al documento.</p>`:''}<div class="doc-top-actions"><div><span class="eyebrow">AZIONI DOCUMENTO</span><small>Salva una nuova versione, approva oppure torna esattamente al punto da cui sei arrivato.</small></div><div class="actions"><button class="btn danger back-to-origin pulse-back" id="backDocs">← Torna indietro</button><button class="btn primary" id="saveDoc">Salva / aggiorna documento</button><button class="btn success" id="approveDoc">${state.docReturn?.normativeWorkflow?'Approva documento e torna all’adempimento':linkedTask?.status==='non_applicabile'?'Approva e valida non applicabilità':state.docReturn?.taskId?'Approva e valida adempimento':'Approva'}</button>${['validation_report','authorization_minutes'].includes(doc.type)&&doc.status==='draft'&&!doc.approvedAt&&!doc.versions?.some(v=>v.reason==='Approvazione')?`<button class="btn danger discard-validation-draft" data-id="${esc(doc.id)}">Elimina bozza verbale</button>`:''}<button class="btn" id="newModelDraft">Nuova bozza dal modello aggiornato</button></div></div><p class="microcopy">Modello: ${esc(doc.templateRevision||'versione precedente')}. Una nuova bozza conserva questo documento e le sue revisioni.</p><div id="documentActionFeedback" class="banner warn" role="alert" tabindex="-1" hidden></div>${linkedTask?.status==="non_applicabile"?`<section class="panel"><strong>Validazione della non applicabilità al caso</strong><p>Il documento collegato deve motivare perché questa attività non è richiesta dal profilo. Per i trasferimenti extra SEE il profilo deve riportare esplicitamente No.</p><label><input type="checkbox" id="docTaskExclusionConfirmed"> Ho verificato il documento e confermo la non applicabilità dell’attività al caso.</label><label class="field"><span>Motivazione e riferimenti nel documento · almeno 30 caratteri *</span><textarea id="docTaskExclusionReason">${esc(linkedTask.exclusionValidation?.reason||"")}</textarea></label></section>`:""}${linkedTask?.evidenceRequired&&linkedTask.status!=="non_applicabile"?`<section class="panel"><strong>Riscontro richiesto per validare l’adempimento</strong><p>${esc(linkedTask.evidenceRequired)}</p><p>Usa gli allegati già validati oppure conferma che il documento contiene effettivamente questi riscontri. Un modello compilato senza prove operative non è sufficiente.</p><label><input type="checkbox" id="docTaskProofConfirmed"> Ho verificato che i riscontri richiesti sono contenuti nel documento.</label><label class="field"><span>Sezioni, pagine e risultati verificati · almeno 30 caratteri se usi il documento come evidenza</span><textarea id="docTaskProofScope">${esc(linkedTask.documentEvidence?.scope||"")}</textarea></label></section>`:""}<div class="editor-shell"><div class="editor-toolbar" role="toolbar" aria-label="Editor documento"><button type="button" aria-label="Annulla ultima modifica" data-cmd="undo">↶</button><button type="button" aria-label="Ripeti ultima modifica" data-cmd="redo">↷</button><button type="button" aria-label="B · Grassetto" data-cmd="bold"><b>B</b></button><button type="button" aria-label="I · Corsivo" data-cmd="italic"><i>I</i></button><button data-block="h2">H2</button><button data-block="p">P</button><button data-cmd="insertUnorderedList">• Lista</button><button data-cmd="insertOrderedList">1. Lista</button><button id="insertTable">Tabella</button><button id="insertField">Campo dinamico</button><button id="insertHeader">Intestazione</button><button id="insertSignature">Firme</button></div><div id="docEditor" class="editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Contenuto del documento: ${esc(doc.title)}">${window.AIGHSecurity.html(doc.html)}</div></div><div class="doc-export-grid single-print"><button class="doc-export-card print-primary-card" id="printDoc"><strong>Stampa / Salva PDF</strong><span>Documento amministrativo impaginato</span><small>Stampa con logo, intestazione dell’Ente, riferimenti, versione e piè di pagina.</small></button></div>`)}

function bindIndividualRisks(){document.querySelectorAll('.validate-individual-risk').forEach(btn=>btn.addEventListener('click',()=>{const rule=btn.dataset.rule;const field=(prefix)=>document.querySelector(`[data-${prefix}="${CSS.escape(rule)}"]`);const level=field('individual-level')?.value,by=field('individual-by')?.value,reason=field('individual-reason')?.value;try{mutate(()=>C.validateIndividualRisk(state.ws,state.caseId,rule,level,by,reason),'Rischio individuale validato; rivalutare il rischio complessivo',{anchor:'validation'})}catch(e){toast(e.message)}}))}
function render(){if(editorDirty&&$('#docEditor')){flushDocumentEditor().then(()=>render()).catch(e=>toast(e.message));return}refreshCaseStatuses();nav();applyNav();if(state.view==='case-hub'&&state.pendingAnchor&&CASE_TABS.has(state.pendingAnchor)){state.caseTab=state.pendingAnchor;state.pendingAnchor=null}let html='';if(state.docId){const d=state.ws.documents.find(x=>x.id===state.docId);if(d)html=editorView(d);else state.docId=null}if(!state.docId){switch(state.view){case'welcome':html=Journey.welcome();break;case'dashboard':html=dashboardView();break;case'entity':html=entityView();break;case'roles':html=rolesView();setTimeout(renderSwim,0);break;case'entity-guidelines':html=entityGuidelinesView();break;case'knowledge':html=knowledgeView();break;case'cases':html=casesView();break;case'new-case':html=newCaseView();break;case'catalog':html=catalogView();break;case'case-hub':html=caseHubView();break;case'register':html=registerView();break;case'incidents':html=incidentsView();break;case'reviews':html=reviewsView();break;case'training':html=trainingView();break;case'deadlines':html=deadlinesView();break;case'todos':html=todosView();break;case'sources':html=sourcesView();break;case'normativa':html=normativaView();break;case'guide':html=Journey.guide();break;case'helpdesk':html=helpdeskView();break;case'support':html=supportView();break;case'accessibility':html=accessibilityView();break;default:html=dashboardView()}}$('#main').innerHTML=html;window.AIGHAccessibility?.prepare(document);updateHeaderIdentity();$$('.top-tool').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));globalHandlers();bind();if(state.view==='normativa')window.PAIAARegulatory?.mount(isAdmin());bindIndividualRisks();bindWizard();bindAssisted();if(state.view!=='case-hub')postRenderEnhance();if(state.view==='case-hub'&&!state.docId&&!state.restoringDocOrigin)Journey.focus()}
