function tipContent(key){const tips={entityType:{title:'Tipologia ente',text:'Scegli prima Ente, Provincia oppure Altro. Se scegli Altro puoi poi specificare la tipologia effettiva dell’ente.'},entityName:{title:'Denominazione ente',text:'Per Enti e Province la denominazione viene precompilata con il prefisso corretto (Ente di / Provincia di).'},entityCity:{title:'Territorio / sede',text:'Indica il territorio o la sede principale utile alla contestualizzazione amministrativa del fascicolo.'},tenantSlug:{title:'Identificativo interno',text:'Identificativo tecnico interno dell’installazione dell’Ente.'},caseName:{title:'Nome caso',text:'Inserisci un titolo chiaro e sintetico del caso d’uso AI.'},caseSystem:{title:'Sistema / prodotto',text:'Indica la piattaforma, il software o il servizio AI usato o in valutazione.'},casePurpose:{title:'Finalità',text:'Descrivi il bisogno amministrativo e l’obiettivo operativo del caso d’uso.'},caseOwner:{title:'Owner',text:'È il referente organizzativo del caso, responsabile del coordinamento del fascicolo.'},ropaStatus:{title:'Stato Registro del trattamento',text:'Serve a capire se il trattamento è già censito nel Registro del trattamento oppure se va aggiornato.'},dpiaDecision:{title:'Valutazione DPIA',text:'La decisione finale resta umana. Se l’esito è SI, il sistema attiva gli adempimenti connessi.'},riskValidation:{title:'Classificazione rischio',text:'La classificazione finale va validata come BASSO, MEDIO o ALTO secondo l’istruttoria.'},processStrip:{title:'Percorso del fascicolo',text:'La fase evidenziata in modo lampeggiante indica il punto del processo in cui si trova il caso.'},workflow:{title:'Workflow interattivo',text:'Rappresenta lo stato del fascicolo e i passaggi attivi, completati o bloccati.'},caseMap:{title:'Mappa del caso',text:'Visualizza in forma sintetica relazioni tra sistema, dati, documenti, evidenze e adempimenti.'},dashboard:{title:'Dashboard direzionale',text:'La dashboard iniziale sintetizza i casi attivi e consente l’accesso rapido ai fascicoli.'}};return tips[key]||{title:'Guida',text:'Indicazione operativa'} }
function helpBubble(key){return `<button type="button" class="help-inline" data-tip="${esc(key)}" aria-label="Apri guida">?</button>`}
function openTip(key){const t=tipContent(key);modal(t.title,`<div class="guide-overlay-copy"><p>${esc(t.text)}</p></div>`)}
function entityPrefix(type){return type==='Ente'?'Ente di ':type==='Provincia'?'Provincia di ':type==='Regione'?'Regione ':type==='Azienda sanitaria'?'Azienda Sanitaria ':type==='Ente strumentale'?'Ente strumentale ':type==='Altro'?'Altro ente ':''}
function stripEntityPrefix(v=''){const prefixes=['Ente di ','Provincia di ','Regione ','Azienda Sanitaria ','Ente strumentale ','Ente ','Altro ente '];const hit=prefixes.find(p=>String(v).toLowerCase().startsWith(p.toLowerCase()));return hit?String(v).slice(hit.length):String(v)}
function setEntityNamePrefix(input,type,force=false){if(!input)return;const value=String(input.value||''),prefix=entityPrefix(type);const hasPrefix=/^(ente di |provincia di |regione |azienda sanitaria |ente strumentale |ente |altro ente )/i.test(value);if(force||!value.trim()||hasPrefix){const rest=stripEntityPrefix(value).trim();input.value=prefix+(rest||'')}input.placeholder=prefix||'Denominazione ente'}
function currentPhase(caseObj){const steps=workflowSteps(caseObj);return steps.find(x=>x.status==='active'||x.status==='hold'||x.status==='pending')||steps[steps.length-1]||{anchor:'overview',label:'CASO',status:'active',statusLabel:'In corso'}}
function addHelpToField(inputSelector,key){const input=$(inputSelector);if(!input)return;const field=input.closest('.field')||input.parentElement;const label=field&&field.querySelector('label, span');if(label&&!label.querySelector('.help-inline'))label.insertAdjacentHTML('beforeend',' '+helpBubble(key))}
