async function zipEntriesFromXlsx(file){const buf=await file.arrayBuffer(),u=new Uint8Array(buf),dv=new DataView(buf);let eocd=-1;for(let i=u.length-22;i>=Math.max(0,u.length-65558);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break}}if(eocd<0)throw new Error('File XLSX non riconosciuto');const count=dv.getUint16(eocd+10,true),central=dv.getUint32(eocd+16,true),dec=new TextDecoder('utf-8'),out={};let p=central;for(let n=0;n<count;n++){if(dv.getUint32(p,true)!==0x02014b50)break;const method=dv.getUint16(p+10,true),cs=dv.getUint32(p+20,true),fn=dv.getUint16(p+28,true),ex=dv.getUint16(p+30,true),cm=dv.getUint16(p+32,true),local=dv.getUint32(p+42,true),name=dec.decode(u.slice(p+46,p+46+fn));const lfn=dv.getUint16(local+26,true),lex=dv.getUint16(local+28,true),start=local+30+lfn+lex,raw=u.slice(start,start+cs);let data;if(method===0)data=raw;else if(method===8&&typeof DecompressionStream!=='undefined'){const stream=new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'));data=new Uint8Array(await new Response(stream).arrayBuffer())}else throw new Error('Compressione XLSX non supportata dal browser');out[name]=data;p+=46+fn+ex+cm}return out}
function xlsxCellRows(entries){const dec=new TextDecoder('utf-8'),parser=new DOMParser(),shared=[];if(entries['xl/sharedStrings.xml']){const doc=parser.parseFromString(dec.decode(entries['xl/sharedStrings.xml']),'application/xml');doc.querySelectorAll('si').forEach(si=>shared.push([...si.querySelectorAll('t')].map(t=>t.textContent||'').join('')))}const bytes=entries['xl/worksheets/sheet1.xml'];if(!bytes)throw new Error('Foglio Caso non trovato');const doc=parser.parseFromString(dec.decode(bytes),'application/xml'),rows=[];doc.querySelectorAll('sheetData row').forEach(row=>{const arr=[];row.querySelectorAll('c').forEach(c=>{const ref=c.getAttribute('r')||'',letters=(ref.match(/[A-Z]+/)||['A'])[0];let col=0;for(const ch of letters)col=col*26+(ch.charCodeAt(0)-64);col--;const t=c.getAttribute('t'),v=c.querySelector('v')?.textContent??'',inline=[...c.querySelectorAll('is t')].map(x=>x.textContent||'').join('');arr[col]=t==='s'?shared[Number(v)]??'':t==='inlineStr'?inline:v});rows.push(arr)});return rows}
function normalizeExcelAnswer(v){v=String(v||'').trim().toLowerCase();if(['si','sì','yes','true','1'].includes(v))return 'yes';if(['no','false','0'].includes(v))return 'no';return 'verify'}
async function importCatalogXlsx(file){const entries=await zipEntriesFromXlsx(file),rows=xlsxCellRows(entries);if(rows.length<3)throw new Error('Nessuna riga dati');const headers=rows[0].map(x=>String(x||'').trim()),idx=k=>headers.indexOf(k);for(const req of ['key','nome','sistema','finalita'])if(idx(req)<0)throw new Error('Colonna mancante: '+req);let count=0;state.ws.catalogExamples=state.ws.catalogExamples||[];for(const row of rows.slice(2)){const key=String(row[idx('key')]||'').trim().replace(/\s+/g,'_').toLowerCase();if(!key)continue;const item={key,name:String(row[idx('nome')]||'').trim(),system:String(row[idx('sistema')]||'').trim(),purpose:String(row[idx('finalita')]||'').trim(),area:String(row[idx('area')]||'').trim(),vendor:String(row[idx('fornitore')]||'Da definire').trim(),answers:{personalData:normalizeExcelAnswer(row[idx('dati_personali')]),specialData:normalizeExcelAnswer(row[idx('dati_particolari')]),affectsPeople:normalizeExcelAnswer(row[idx('impatto_persone')]),automatedDecision:normalizeExcelAnswer(row[idx('decisione_automatizzata')]),highRiskPossible:normalizeExcelAnswer(row[idx('possibile_alto_rischio')]),humanOversight:normalizeExcelAnswer(row[idx('supervisione_umana')]),externalVendor:normalizeExcelAnswer(row[idx('fornitore_esterno')]),transferUnknown:normalizeExcelAnswer(row[idx('trasferimenti_extra_see')]),logging:normalizeExcelAnswer(row[idx('logging')]),providerTraining:normalizeExcelAnswer(row[idx('training_provider')]),accessControls:normalizeExcelAnswer(row[idx('controlli_accesso')]),procurement:normalizeExcelAnswer(row[idx('procurement')]),aiLiteracy:normalizeExcelAnswer(row[idx('ai_literacy')])}};if(!item.name||!item.system||!item.purpose)continue;const i=state.ws.catalogExamples.findIndex(x=>x.key===key);if(i>=0)state.ws.catalogExamples[i]=item;else state.ws.catalogExamples.push(item);count++}if(!count)throw new Error('Nessun caso valido nelle righe compilate');return count}
function setupPublicNewCase(){const open=$('#publicNewCaseButton'),panel=$('#publicCasePanel'),close=$('#closePublicCase'),form=$('#publicNewCaseForm');if(!open||!panel||!form)return;const dismiss=()=>{panel.close();panel.classList.add('hidden');open.focus()};open.onclick=()=>{panel.classList.remove('hidden');panel.showModal();window.AIGHAccessibility?.prepare(panel);panel.querySelector('input')?.focus()};if(close)close.onclick=dismiss;panel.addEventListener('cancel',e=>{e.preventDefault();dismiss()});form.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form).entries());try{localStorage.setItem('aigh_public_case_draft',JSON.stringify(data));publicCaseDraftFallback=data}catch(err){publicCaseDraftFallback=data}$('#publicCaseMessage').textContent='Bozza pronta. Accedi: il caso verrà creato automaticamente nell’Ente configurato.';$('#publicCaseMessage').classList.remove('hidden');dismiss()}}
async function consumePublicCaseDraft(){let raw='';try{raw=localStorage.getItem('aigh_public_case_draft')||''}catch(e){}if(!raw&&publicCaseDraftFallback)raw=JSON.stringify(publicCaseDraftFallback);if(!raw)return false;try{const data=JSON.parse(raw);if(!data?.name||!data?.purpose)return false;const c=C.createCase(state.ws,data);state.caseId=c.id;state.questionIndex=0;state.view='case-hub';state.caseTab='assessment';state.pendingAnchor='assessment';try{localStorage.removeItem('aigh_public_case_draft')}catch(e){}publicCaseDraftFallback=null;await persist();toast('Nuovo caso creato dalla bozza preparata prima dell’accesso');return true}catch(e){console.error(e);return false}}
function printAdministrativeDocument(){const d=state.ws.documents.find(x=>x.id===state.docId),ed=$('#docEditor');if(!d||!ed)return;const e=state.ws.entity||{},logo=e.logo?`<img class="print-logo" src="${esc(e.logo)}" alt="Logo ${esc(e.name||'Ente')}">`:'';const contact=[e.address,e.phone,e.email,e.pec].filter(Boolean).map(esc).join(' · ');const w=window.open('','_blank');if(!w){toast('Il browser ha bloccato la finestra di stampa');return}const caseName=d.caseId?state.ws.cases.find(c=>c.id===d.caseId)?.name||'':'';w.document.write(`<!doctype html><html lang="it"><head><meta charset="utf-8"><title>${esc(d.title)}</title><style>@page{size:A4;margin:25mm 18mm 22mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#182b3c;font-size:11pt;line-height:1.5;margin:0}.print-head{display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center;border-bottom:2px solid #0b5fa5;padding-bottom:12px;margin-bottom:22px}.print-logo{max-width:105px;max-height:70px;object-fit:contain}${window.PAIAAInstitutionalDocuments?.CSS||''}.print-org strong{display:block;font-size:15pt;color:#0b5fa5}.print-org small{display:block;color:#566d80;margin-top:3px}.print-meta{border:1px solid #cbd9e5;border-radius:8px;padding:10px 12px;margin:0 0 20px;background:#f7fafc;display:grid;grid-template-columns:1fr 1fr;gap:6px 18px}.print-meta b{color:#37546d}h1,h2,h3{color:#173b59;page-break-after:avoid}table{width:100%;border-collapse:collapse;margin:12px 0}th,td{border:1px solid #aebdca;padding:7px;vertical-align:top}th{background:#edf4f9}.chip{border:1px solid #b9cbd8;border-radius:10px;padding:2px 6px}.print-footer{position:fixed;bottom:-13mm;left:0;right:0;border-top:1px solid #b9c9d6;padding-top:6px;font-size:8.5pt;color:#60778a;display:flex;justify-content:space-between}.print-content img{max-width:100%}.print-content p,.print-content li{orphans:3;widows:3}</style></head><body><header class="print-head">${ed.innerHTML.includes('class="paiaa-letterhead"')?'':logo}<div class="print-org"><strong>${esc(e.name||'Ente')}</strong><small>${esc(e.office||'')}</small><small>${contact||esc(e.city||'')}</small></div></header><section class="print-meta"><div><b>Documento:</b> ${esc(d.title)}</div><div><b>Versione:</b> ${esc(d.version||1)}</div>${caseName?`<div><b>Fascicolo:</b> ${esc(caseName)}</div>`:''}<div><b>Data stampa:</b> ${new Date().toLocaleDateString('it-IT')}</div><div><b>Stato:</b> ${esc(d.status==='approved'?'Approvato nel fascicolo':'Bozza')}</div></section><main class="print-content">${window.AIGHSecurity.html(ed.innerHTML)}</main><footer class="print-footer"><span>${esc(e.name||'Ente')} · AI Governance Hub – PA Lucane</span><span>${esc(d.title)} · v${esc(d.version||1)}</span></footer><script>window.onload=()=>{setTimeout(()=>window.print(),180)}<\/script></body></html>`);w.document.close()}
function enhanceNewCaseForm(){const form=$('#newCaseForm');if(!form||form.dataset.enhanced)return;form.dataset.enhanced='1';addHelpToField('#newCaseForm [name="name"]','caseName');addHelpToField('#newCaseForm [name="system"]','caseSystem');addHelpToField('#newCaseForm [name="purpose"]','casePurpose');addHelpToField('#newCaseForm [name="owner"]','caseOwner');bindTipButtons(form)}
function dashboardProcessPanel(){if(!state.ws.cases.length)return '<div class="panel"><div class="empty">Nessun processo attivo.</div></div>';const list=prioritizedCases();return `<div id="dashboardProcessRail" class="panel process-dashboard"><div class="section-head"><div><span class="eyebrow">CASI PRIORITARI</span><h3>Prossime attività ${helpBubble('dashboard')}</h3><p>Mostra al massimo sei casi che richiedono attenzione; l’elenco completo resta nella pagina Casi AI.</p></div><button class="btn small" type="button" data-view="cases">Tutti i casi</button></div><div class="process-card-grid">${list.map(c=>{const phase=currentPhase(c),comp=C.assessmentCompletion(c),next=nextCaseAction(c);return `<button class="process-card open-case" data-id="${c.id}" type="button"><div class="process-card-head"><strong>${esc(c.name)}</strong>${statusBadge(c.status)}</div><div class="process-card-meta"><span class="phase-pill ${phase.status==='hold'?'hold':'live'}">${esc(phase.label)}</span><small>${esc(next.label)}</small></div><div class="progress-block compact"><div class="progress"><span style="width:${comp.pct}%"></span></div><small>${comp.pct}% assessment completato</small></div></button>`}).join('')}</div></div>`}
function enhanceDashboard(){if(state.view!=='dashboard')return;const kpi=$('.dashboard-kpi-groups');if(kpi&&!$('#dashboardProcessRail'))kpi.insertAdjacentHTML('afterend',dashboardProcessPanel());ensurePanelButton('#chartOwners','dashboard-owners');ensurePanelButton('#chartAreas','dashboard-areas');$$('[data-insight]').forEach(b=>b.onclick=()=>openInsight(b.dataset.insight));{const b=$('#closeDashboardDetail');if(b)b.onclick=()=>$('#dashboardDrilldown')?.classList.add('is-collapsed')}bindTipButtons();bindDashboardRows()}
function enhanceCaseOverview(){if(state.view!=='case-hub'||state.caseTab!=='overview')return;const c=cur();if(!c)return;const phase=currentPhase(c).anchor;$$('.case-tab').forEach(n=>{if(n.dataset.tab===phase)n.classList.add('active-phase')});$$('[data-insight]').forEach(b=>b.onclick=()=>openInsight(b.dataset.insight));bindTipButtons();if(window.AIGHFriendly)window.AIGHFriendly.init()}
